@push('scripts')<script>(function(){let step=1;const steps=[...document.querySelectorAll('.wizard-step')],chips=[...document.querySelectorAll('.wizard-chip')],prev=document.getElementById('prevBtn'),next=document.getElementById('nextBtn'),save=document.getElementById('saveBtn');function draw(){steps.forEach(x=>x.style.display=+x.dataset.step===step?'block':'none');chips.forEach(x=>x.classList.toggle('md-chip--selected',+x.dataset.step===step));prev.style.visibility=step===1?'hidden':'visible';next.style.display=step===6?'none':'inline-flex';save.style.display=step===6?'inline-flex':'none';}prev.onclick=()=>{step=Math.max(1,step-1);draw()};next.onclick=()=>{step=Math.min(6,step+1);draw()};chips.forEach(c=>c.onclick=()=>{step=+c.dataset.step;draw()});draw();})();</script>@endpush
